// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(address sender1, uint256 amount1, address sender2, uint256 amount2) public {
        vm.assume(sender1 != address(0) && sender2 != address(0) && sender1 != sender2);
        vm.assume(amount1 > 0 && amount2 > 0);
        vm.assume(amount1 < type(uint256).max / 2 && amount2 < type(uint256).max / 2);
        vm.deal(sender1, amount1);
        vm.deal(sender2, amount2);

        vm.prank(sender1);
        c.addToBalance{value: amount1}();

        vm.prank(sender2);
        c.addToBalance{value: amount2}();

        uint256 balance1 = c.getBalance(sender1);
        uint256 balance2 = c.getBalance(sender2);
        uint256 totalBalance = balance1 + balance2;
        uint256 expectedTotal = amount1 + amount2;
        assertTrue(totalBalance == expectedTotal);
    }
}
